'use strict';

// MODULES //

var logger = require( 'debug' );
var join = require( '@stdlib/array/base/join' );
var lowercase = require( '@stdlib/string/lowercase' );
var trim = require( '@stdlib/string/trim' );
var replace = require( '@stdlib/string/replace' );
var format = require( '@stdlib/string/format' );
var hash = require( './hash.js' );
var provenance = require( './provenance.js' );
var diagnostic = require( './diagnostic.js' );
var structure = require( './structure.js' );
var convert = require( './convert.js' );
var validateDocument = require( './validate_document.js' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:build' );


// FUNCTIONS //

/**
* Returns the line-ending style of a string.
*
* @private
* @param {string} source - source string
* @returns {string} line-ending style
*/
function lineEnding( source ) {
	var remainder;
	var crlf;
	var lf;
	var cr;

	// Remove CRLF pairs before checking for standalone newline characters. This distinguishes a uniform CRLF document from one having mixed line endings...
	remainder = replace( source, /\r\n/g, '' );

	crlf = /\r\n/.test( source );
	lf = /\n/.test( remainder );
	cr = /\r/.test( remainder );
	if ( !crlf && !lf && !cr ) {
		return 'none';
	}
	if ( crlf && !lf && !cr ) {
		return 'crlf';
	}
	if ( lf && !crlf && !cr ) {
		return 'lf';
	}
	return 'mixed';
}

/**
* Returns a normalized reference identifier.
*
* @private
* @param {string} value - identifier
* @returns {string} normalized identifier
*/
function normalizeIdentifier( value ) {
	return lowercase( trim( replace( value, /[\t\n\r ]+/g, ' ' ) ) );
}

/**
* Collects definition resources.
*
* @private
* @param {Object} node - MDAST node
* @param {Object} state - conversion state
* @returns {void}
*/
function collectDefinitions( node, state ) {
	var normalized;
	var resource;
	var selected;
	var ordinal;
	var index;
	var path;
	var i;

	// Remark permits definitions at any depth. Collect all definitions before projecting flow content so that forward and nested references resolve...
	if ( node.type === 'definition' ) {
		index = state.document.resources.definitionIndex;
		normalized = normalizeIdentifier( node.identifier );
		ordinal = state.definitionCounts[ normalized ] || 0;
		selected = !state.definitions[ normalized ];
		resource = {
			'id': format( 'definition[%s]', state.document.resources.definitions.length ),
			'identifier': node.identifier,
			'normalizedIdentifier': normalized,
			'ordinal': ordinal,
			'url': node.url,
			'title': node.title || null,
			'selected': selected,
			'source': state.provenance.source( [ node ] )
		};
		state.definitionCounts[ normalized ] = ordinal + 1;
		state.document.resources.definitions.push( resource );
		debug( 'Collected definition resource: id=%s identifier=%s ordinal=%d selected=%s', resource.id, normalized, ordinal, selected );

		path = join( state.provenance.path( node ), '.' );
		state.definitionNodes[ path ] = resource.id;

		// CommonMark uses the first definition for a normalized identifier. Keep duplicates in source order, while indexing only the effective resource...
		if ( selected ) {
			state.definitions[ normalized ] = resource;
			index[ normalized ] = resource.id;
		} else {
			diagnostic( state, 'warning', 'duplicate-definition', format( 'Definition `%s` is declared more than once; the first declaration is effective.', normalized ), node, {
				'identifier': normalized,
				'selectedRef': state.definitions[ normalized ].id,
				'duplicateRef': resource.id
			});
		}
	}
	// Definitions may be nested in block quotes or list items, so traverse every child rather than limiting collection to root-level definition nodes...
	if ( node.children ) {
		for ( i = 0; i < node.children.length; i++ ) {
			collectDefinitions( node.children[ i ], state );
		}
	}
}

/**
* Returns a child hash.
*
* @private
* @param {Object} node - semantic node
* @returns {string} semantic or tree hash
*/
function childHash( node ) {
	return node.treeHash || node.semanticHash || node.payloadHash;
}

/**
* Finalizes semantic container hashes and removes internal fields.
*
* @private
* @param {Object} node - semantic node or document
* @returns {void}
*/
function finalize( node ) {
	var children;
	var payload;
	var i;

	if ( node.children ) {
		// Finalize descendants first so that a container hash commits to the fully finalized semantic identity of each child in document order...
		children = [];
		for ( i = 0; i < node.children.length; i++ ) {
			finalize( node.children[ i ] );
			children.push( childHash( node.children[ i ] ) );
		}
		if ( node.type === 'section' || node.type === 'topic' ) {
			// Container hashes include structural meaning in addition to child hashes. This prevents identical content under different roles from colliding...
			payload = {
				'type': node.type,
				'role': node.role,
				'headingRef': node.headingRef,
				'children': children
			};
			if ( node.type === 'section' ) {
				payload.path = node.path;
				payload.ordinal = node.ordinal;
				payload.recovered = node.recovered;
			}
			node.treeHash = hash( payload );
			debug( 'Finalized semantic container: id=%s type=%s children=%d', node.id, node.type, children.length );
		}
	}
	// Internal counters and traversal context are construction details and are deliberately excluded from both the schema and returned document:
	delete node.internal;
}

/**
* Collects semantic node IDs and reports duplicates.
*
* @private
* @param {Object} node - semantic node
* @param {Object} ids - ID set
* @param {Object} state - conversion state
* @returns {void}
*/
function collectIDs( node, ids, state ) {
	var i;

	// IDs are allocated per parent, so we should protect against a future allocator change accidentally producing ambiguous references...
	if ( node.id ) {
		if ( ids[ node.id ] ) {
			diagnostic( state, 'error', 'id-collision', format( 'Semantic node ID `%s` is not unique.', node.id ), void 0, {
				'id': node.id
			});
		}
		ids[ node.id ] = true;
	}
	if ( node.children ) {
		for ( i = 0; i < node.children.length; i++ ) {
			collectIDs( node.children[ i ], ids, state );
		}
	}
}

/**
* Reports root source nodes missing accounting records.
*
* @private
* @param {Object} tree - source MDAST tree
* @param {Object} state - conversion state
* @returns {void}
*/
function validateAccounting( tree, state ) {
	var key;
	var i;

	debug( 'Validating source accounting: rootChildren=%d', tree.children.length );

	// Every root MDAST child must have an explicit disposition. Nested nodes are recorded only when a transformation changes their representation...
	for ( i = 0; i < tree.children.length; i++ ) {
		key = join( state.provenance.path( tree.children[ i ] ), '.' );
		if ( !state.accounted[ key ] ) {
			diagnostic( state, 'error', 'unaccounted-source-node', 'Root source node has no accounting disposition.', tree.children[ i ], {
				'astPath': state.provenance.path( tree.children[ i ] )
			});
		}
	}
	debug( 'Validated source accounting: records=%d', state.document.accounting.length );
}

/**
* Appends JSON Schema validation diagnostics.
*
* @private
* @param {Object} state - conversion state
* @returns {void}
*/
function validateSchema( state ) {
	var errors;
	var i;

	errors = validateDocument( state.document );
	debug( 'Validated semantic document schema: errors=%d', errors.length );

	// Schema errors are returned as normal document diagnostics, allowing "strict" mode to reject the document without losing the partial conversion result...
	for ( i = 0; i < errors.length; i++ ) {
		diagnostic( state, 'error', 'schema-validation', 'Generated semantic document does not satisfy the document schema.', void 0, {
			'keyword': errors[ i ].keyword,
			'dataPath': errors[ i ].dataPath,
			'message': errors[ i ].message,
			'params': errors[ i ].params
		});
	}
}

/**
* Compares two accounting records by MDAST traversal path.
*
* @private
* @param {Object} a - first accounting record
* @param {Object} b - second accounting record
* @returns {number} comparison result
*/
function compareAccounting( a, b ) {
	var len;
	var i;

	// Compare path components numerically to restore depth-first MDAST order. A parent sorts before descendants when one path is a prefix of the other...
	if ( a.astPath.length < b.astPath.length ) {
		len = a.astPath.length;
	} else {
		len = b.astPath.length;
	}
	for ( i = 0; i < len; i++ ) {
		if ( a.astPath[ i ] !== b.astPath[ i ] ) {
			return a.astPath[ i ] - b.astPath[ i ];
		}
	}
	return a.astPath.length - b.astPath.length;
}


// MAIN //

/**
* Builds a semantic document from an MDAST tree and Markdown source.
*
* @private
* @param {Object} tree - MDAST tree
* @param {string} source - source Markdown
* @param {Buffer} bytes - exact input bytes
* @param {Options} options - conversion options
* @returns {Object} semantic document
*/
function build( tree, source, bytes, options ) {
	var structural;
	var state;
	var doc;

	debug( 'Building semantic document: profile=%s mode=%s rootChildren=%d bytes=%d', options.profile, options.mode, tree.children.length, bytes.length );

	// Initialize the complete public envelope up front. Conversion stages mutate only these arrays/references and private state stored alongside the document...
	doc = {
		'schemaVersion': '1.0.0',
		'profile': {
			'name': options.profile,
			'version': '1.0.0'
		},
		'source': {
			'mediaType': 'text/markdown',
			'digest': hash( bytes ),
			'encoding': 'utf-8',
			'bom': bytes.length >= 3 && bytes[ 0 ] === 0xEF && bytes[ 1 ] === 0xBB && bytes[ 2 ] === 0xBF,
			'lineEnding': lineEnding( source )
		},
		'titleRef': null,
		'summaryRef': null,
		'children': [],
		'resources': {
			'definitions': [],
			'definitionIndex': Object.create( null ),
			'directives': [],
			'embeddedCode': []
		},
		'accounting': [],
		'diagnostics': []
	};
	state = {
		'document': doc,
		'options': options,
		'accounted': Object.create( null ),
		'forceRaw': Object.create( null ),
		'definitions': Object.create( null ),
		'definitionCounts': Object.create( null ),
		'definitionNodes': Object.create( null ),
		'directiveNodes': Object.create( null ),
		'directiveAccounting': Object.create( null ),
		'undefinedReferences': Object.create( null ),
		'titleNode': null,
		'lastRootWasTitle': false
	};

	debug( 'Indexing source provenance and definitions...' );

	// Build provenance and resource indexes before semantic conversion. Projected Markdown can therefore resolve definitions regardless of declaration order:
	state.provenance = provenance( tree, source, options );
	collectDefinitions( tree, state );
	debug( 'Indexed source resources: definitions=%d', doc.resources.definitions.length );

	// Recover document structure first, and then convert the recovered hierarchy to canonical semantic flow:
	debug( 'Recovering structural sections...' );
	structural = structure( tree, state );
	debug( 'Recovered structural sections: rootChildren=%d', structural.rawChildren.length );

	debug( 'Converting recovered structure to semantic flow...' );
	convert( structural, state );
	debug( 'Converted semantic flow: children=%d directives=%d embeddedCode=%d diagnostics=%d', doc.children.length, doc.resources.directives.length, doc.resources.embeddedCode.length, doc.diagnostics.length );

	// Audit and order source dispositions before removing construction-only state:
	debug( 'Auditing source accounting...' );
	validateAccounting( tree, state );
	doc.accounting.sort( compareAccounting );
	debug( 'Audited source accounting: records=%d', doc.accounting.length );

	// Finalization computes bottom-up hashes and verifies document-local IDs:
	debug( 'Finalizing semantic document...' );
	collectIDs( doc, Object.create( null ), state );
	finalize( doc );
	delete doc.type;
	debug( 'Finalized semantic document.' );

	// Validate last so that schema failures describe the exact object returned in permissive mode or attached to a strict-mode error:
	validateSchema( state );
	debug( 'Completed semantic document build: diagnostics=%d', doc.diagnostics.length );
	return doc;
}


// EXPORTS //

module.exports = build;
